-- ============================================================================
-- FinAgent OS — Migration 0005: hitl_queue + SoD RLS
-- ============================================================================
-- The HITL Queue holds pending human-approval requests generated by agents
-- that produce REQUIRE_HUMAN policy outcomes. Every row represents one
-- invocation awaiting a decision from a process owner.
--
-- The core control — FAO-GOV-004 — is segregation of duties enforced at
-- the database layer: a process owner cannot approve their own agent
-- invocation. The check is a Row-Level Security WITH CHECK clause
-- that Postgres evaluates BEFORE committing the approval UPDATE. If the
-- authenticated user (approver) equals the agent_invoker_id on the row,
-- the update is rejected and nothing is written.
--
-- This is the JD's "access controls confirmed" in concrete form:
-- segregation of duties is a Postgres RLS policy, not documentation.
--
-- Control IDs implemented:
--   FAO-GOV-004  HITL Gateway + segregation-of-duties enforcement
--   FAO-GOV-008  Correlation ID threading (UUID per execution)
--
-- Author: Rizwan Ahmed, ACCA · Velocyt Consulting
-- Date:   2026-04-20
-- ============================================================================

CREATE TABLE public.hitl_queue (
  -- Primary key
  hitl_id               BIGSERIAL      PRIMARY KEY,

  -- Correlation ID threads back to the shadow_ledger entry that triggered
  -- this HITL request. One HITL row per unique correlation_id (a single
  -- agent execution generates at most one pending approval request).
  correlation_id        UUID           NOT NULL UNIQUE,

  -- The agent that produced the REQUIRE_HUMAN outcome. FK to agent_registry.
  agent_id              TEXT           NOT NULL REFERENCES public.agent_registry(agent_id) ON DELETE RESTRICT,

  -- The process owner who invoked the agent — i.e. the person whose action
  -- triggered this HITL request. Cannot be the same as the approver.
  -- This is the column the SoD check compares against auth.uid() at
  -- approval time.
  agent_invoker_id      UUID           NOT NULL REFERENCES public.process_owners(id) ON DELETE RESTRICT,

  -- Created at
  created_at            TIMESTAMPTZ    NOT NULL DEFAULT NOW(),

  -- Risk tier at time of HITL creation (captured here, not joined, so
  -- historical HITL records reflect the tier active at decision time).
  risk_tier             risk_tier      NOT NULL,

  -- Sub-tier for STANDARD vs CRITICAL routing
  sub_tier              policy_sub_tier NOT NULL DEFAULT 'STANDARD',

  -- Policy rationale — the "why" of the REQUIRE_HUMAN outcome. Written
  -- by the policy engine, presented to the approver.
  policy_rationale      TEXT           NOT NULL,

  -- AI-generated human approval brief. Advisory only — summarizes the
  -- situation for the reviewer. Does not alter the approval gate.
  -- FAO-REC-009 for the reconciliation agent specifically.
  ai_human_brief        TEXT,

  -- The approver's identity. NULL until decision is rendered. UPDATE
  -- policy enforces this can never equal agent_invoker_id.
  approver_id           UUID           REFERENCES public.process_owners(id) ON DELETE SET NULL,

  -- The decision itself.
  decision              hitl_decision  NOT NULL DEFAULT 'PENDING',

  -- When the decision was rendered
  decided_at            TIMESTAMPTZ,

  -- Free-text notes from the approver
  decision_notes        TEXT,

  -- SLA — when this HITL request escalates if still PENDING. Populated
  -- at INSERT from agent_registry.sla_max_hitl_resolution_hrs.
  timeout_at            TIMESTAMPTZ,

  -- Coherence check: if decision is APPROVED or REJECTED, approver_id must
  -- be populated and decided_at must be set. If PENDING, all three are
  -- permitted to be NULL.
  CONSTRAINT hitl_decision_coherence CHECK (
    (decision = 'PENDING' AND approver_id IS NULL AND decided_at IS NULL)
    OR
    (decision IN ('APPROVED', 'REJECTED') AND approver_id IS NOT NULL AND decided_at IS NOT NULL)
  )
);

-- --- Indexes ---------------------------------------------------------------

CREATE INDEX idx_hitl_queue_correlation_id
  ON public.hitl_queue(correlation_id);

CREATE INDEX idx_hitl_queue_agent_id
  ON public.hitl_queue(agent_id);

-- Most-common dashboard query: "show me all pending HITL requests".
-- Partial index keeps it tight since most historical rows are decided.
CREATE INDEX idx_hitl_queue_pending
  ON public.hitl_queue(decision, created_at)
  WHERE decision = 'PENDING';

-- Timeout queries for escalation jobs
CREATE INDEX idx_hitl_queue_timeout
  ON public.hitl_queue(timeout_at)
  WHERE timeout_at IS NOT NULL AND decision = 'PENDING';

-- ============================================================================
-- RLS: SEGREGATION OF DUTIES ENFORCEMENT (FAO-GOV-004)
-- ============================================================================

ALTER TABLE public.hitl_queue ENABLE ROW LEVEL SECURITY;

-- SELECT: authenticated users read the queue. Dashboards render it;
-- process owners see pending approvals requiring their attention.
CREATE POLICY "Authenticated users can read hitl_queue"
  ON public.hitl_queue
  FOR SELECT
  TO authenticated
  USING (true);

-- INSERT: service_role only. Agents create HITL requests as part of
-- their n8n workflow execution, via the Supabase service key. End-user
-- identities never directly create HITL rows.
CREATE POLICY "Only service_role can insert hitl_queue"
  ON public.hitl_queue
  FOR INSERT
  TO service_role
  WITH CHECK (true);

-- UPDATE: authenticated users can update hitl_queue rows IF AND ONLY IF
-- their authenticated UUID does NOT equal the row's agent_invoker_id.
-- This is the segregation-of-duties check — a process owner cannot
-- approve or reject an invocation they themselves triggered.
--
-- The USING clause gates which rows are visible for UPDATE.
-- The WITH CHECK clause gates what the new row state is allowed to be.
-- Both conditions enforce the SoD rule: approver != invoker.
CREATE POLICY "SoD: approver cannot be invoker"
  ON public.hitl_queue
  FOR UPDATE
  TO authenticated
  USING (
    (select auth.uid()) != agent_invoker_id
  )
  WITH CHECK (
    (select auth.uid()) != agent_invoker_id
    AND
    (approver_id IS NULL OR approver_id = (select auth.uid()))
  );

-- Service role can bypass SoD for administrative overrides (e.g.
-- cancelling a hung request). Separate policy so the audit trail
-- distinguishes admin actions from user approvals.
CREATE POLICY "Service role can update hitl_queue"
  ON public.hitl_queue
  FOR UPDATE
  TO service_role
  USING (true)
  WITH CHECK (true);

-- NO DELETE POLICY. HITL history is preserved; decided rows are kept
-- for audit. Deprecation is via timeout expiry, not deletion.

-- --- Comments for introspection --------------------------------------------

COMMENT ON TABLE  public.hitl_queue                         IS 'FAO-GOV-004: Pending human-approval requests. SoD enforced at RLS layer: approver_id != agent_invoker_id.';
COMMENT ON COLUMN public.hitl_queue.agent_invoker_id        IS 'The process owner who triggered the agent run. RLS prevents this identity from approving their own invocation.';
COMMENT ON COLUMN public.hitl_queue.approver_id             IS 'NULL until decision rendered. RLS WITH CHECK enforces approver != invoker.';
